const cfg = {};
$('Read Run_Config').all().forEach((i) => { if (i.json.Setting) cfg[String(i.json.Setting).trim()] = i.json.Value; });
const limit = parseInt(cfg.Searches_Per_Run, 10) || 5;

const pending = $('Read Search_Queue').all()
  .map((i) => i.json)
  .filter((r) => r.Search_ID && String(r.Status || '').trim() === 'Pending')
  .slice(0, limit);

return pending.map((r) => ({
  json: { Search_ID: r.Search_ID, City: r.City, Keyword: r.Keyword, Mode: r.Mode, Query: r.Query },
}));

const cfg = {};
$('Read Run_Config').all().forEach((i) => { if (i.json.Setting) cfg[String(i.json.Setting).trim()] = i.json.Value; });
const perQuery = Math.min(parseInt(cfg.Results_Per_Query, 10) || 10, 10);
const upDays = parseInt(cfg.Upcoming_Window_Days, 10) || 90;
const recDays = parseInt(cfg.Recent_Window_Days, 10) || 30;

// --- AUTO FILTER (junk pehle hi Rejected mark ho jaye) ---
const BAD_DOMAINS = ['nhs.uk', 'gov.uk', 'ac.uk', 'tate.org.uk', 'indeed.com', 'glassdoor.co.uk', 'reed.co.uk', 'totaljobs.com', 'yell.com', 'wikipedia.org'];
const BAD_WORDS = /\b(careers?|jobs?|vacanc\w*|opening hours|opening times|pharmacy first|find a pharmacy|store locator|near me)\b/i;
const hostOf = (u) => { try { return new URL(u).hostname.replace(/^www\./, '').toLowerCase(); } catch (e) { return ''; } };
const autoReason = (o, mode) => {
  const h = hostOf(o.link);
  if (BAD_DOMAINS.some((d) => h === d || h.endsWith('.' + d))) return 'AUTO: irrelevant site (' + h + ')';
  if (BAD_WORDS.test((o.title || '') + ' ' + (o.snippet || ''))) return 'AUTO: irrelevant page (jobs/hours/directory)';
  const dateStr = String(o.date || '');
  if (/years? ago/i.test(dateStr)) return 'AUTO: old article (' + dateStr + ')';
  const t = Date.parse(dateStr);
  if (!isNaN(t)) {
    const age = (Date.now() - t) / 86400000;
    const win = mode === 'Upcoming' ? upDays : recDays;
    if (age > win) return 'AUTO: old article (' + dateStr + ')';
  }
  return '';
};

const norm = (u) => {
  try {
    const x = new URL(String(u).trim());
    return (x.hostname.replace(/^www\./, '') + x.pathname).replace(/\/+$/, '').toLowerCase();
  } catch (e) {
    return String(u || '').trim().toLowerCase();
  }
};
const hash = (s) => {
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
  return h.toString(16).padStart(8, '0');
};
const errorOf = (r) => {
  if (!r || !r.error) return '';
  return typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error));
};
const isZero = (msg) => /hasn't returned any results/i.test(msg);

const picks = $('Pick Pending').all().map((i) => i.json);
const existing = new Set(
  $('Read Opening_Candidates').all().map((i) => norm(i.json.Source_URL)).filter(Boolean)
);
const seen = new Set();
const today = new Date().toISOString().slice(0, 10);
const out = [];

$input.all().forEach((it, idx) => {
  const q = picks[idx];
  if (!q) return;
  const r = it.json || {};
  const msg = errorOf(r);
  if (msg && !isZero(msg)) return; // Error query: koi candidate save nahi hoga
  (r.organic_results || []).slice(0, perQuery).forEach((o) => {
    if (!o.link) return;
    const key = norm(o.link);
    if (existing.has(key) || seen.has(key)) return; // duplicate source URL
    seen.add(key);
    const reason = autoReason(o, q.Mode);
    out.push({
      json: {
        Candidate_ID: 'C-' + hash(key),
        Search_ID: q.Search_ID,
        City: q.City,
        Keyword: q.Keyword,
        Mode: q.Mode,
        Title: o.title || '',
        Snippet: o.snippet || '',
        Source_URL: o.link,
        Source_Date: o.date || '',
        Found_On: today,
        Review_Status: reason ? 'Rejected' : 'New',
        Business_Name: '',
        Location: '',
        Opening_Date: '',
        Reviewer_Notes: reason,
        Processed: '',
      },
    });
  });
});

if (!out.length) return [{ json: { _empty: true } }];
return out;

const cfg = {};
$('Read Run_Config').all().forEach((i) => { if (i.json.Setting) cfg[String(i.json.Setting).trim()] = i.json.Value; });
const perQuery = Math.min(parseInt(cfg.Results_Per_Query, 10) || 10, 10);

const errorOf = (r) => {
  if (!r || !r.error) return '';
  return typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error));
};
const isZero = (msg) => /hasn't returned any results/i.test(msg);

const picks = $('Pick Pending').all().map((i) => i.json);
const resp = $('SerpApi Search').all().map((i) => i.json);
const now = new Date().toISOString();

return picks.map((q, idx) => {
  const r = resp[idx] || {};
  const msg = errorOf(r);
  if (msg && !isZero(msg)) {
    return { json: { Search_ID: q.Search_ID, Status: 'Error', Results_Count: '', Last_Run: now, Error_Message: String(msg).slice(0, 200) } };
  }
  const n = Math.min((r.organic_results || []).length, perQuery);
  return { json: { Search_ID: q.Search_ID, Status: 'Completed', Results_Count: n, Last_Run: now, Error_Message: '' } };
});
